properties.query:
let api_events = AzureActivity | where OperationNameValue has_any ("Microsoft.Compute/virtualMachines/write", "Microsoft.ContainerInstance/containerGroups/write") and ActivityStatusValue == "Success" | summarize api_time=min(TimeGenerated) by Caller, ResourceGroup;
let cpu_events = Perf | where ObjectName == "Processor" and CounterName == "% Processor Time" | summarize avg_cpu=avg(CounterValue) by Computer, bin(TimeGenerated, 5m) | where avg_cpu > 95;
api_events | join kind=inner cpu_events on $left.ResourceGroup == $right.Computer | where cpu_events_TimeGenerated - api_time between (0min .. 120min)
